<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Http\Requests\StoreReviewRequest; use App\Models\Product; class ReviewController extends Controller { public function store(StoreReviewRequest $r,Product $product){$review=$product->reviews()->updateOrCreate(['user_id'=>$r->user()->id],$r->validated()+['is_approved'=>false]);return response()->json(['data'=>$review],201);} }
